extension Fuzz {
extension OperatorError {
  /// Produce the syntax node at which a diagnostic should be displayed.
  var diagnosticDisplayNode: Syntax  {
    switch self {
    case .incomparableOperators(let leftOperator, _, _,
_):
      return Syntax(leftOperator)

    case .missingOperator(_, let node):
      return node

    case .operatorAlreadyExists(_, let newOperator):
      return Syntax(newOperator.syntax ?? newOperator.synthesizedSyntax())

    case .missingGroup(_, let node):
      return node

    case .groupAlreadyExists(_, let newGroup):
      return Syntax(newGroup.syntax ?? newGroup.synthesizedSyntax())
    }
  }

  /// Produce a diagnostic for a given operator-precedence error.
  public var asDiagnostic: Diagnostic {
    .init(node: diagnosticDisplayNode, message: self)
  }
}
}

extension Fuzz {
private extension SyntaxProtocol {
  /// Retrieve the qualified type for the nearest extension or name decl.
  ///
  /// For example, for `struct Foo { struct Bar {} }`, calling this on the
  /// inner struct (`Bar`) will return `Foo.Bar`.
  var syntacticQualifiedTypeContext: TypeSyntax? {
    if let ext = self.as(ExtensionDeclSyntax.self) {
      // Don't handle nested 'extension' cases - they are invalid anyway.
      return ext.extendedType.trimmed
    }

    let base = self.parent?.syntacticQualifiedTypeContext
    if let named = self.asProtocol(NamedDeclSyntax.self) {
      if let base = base {
        return TypeSyntax (MemberTypeSyntax(baseType: base, name: named.name.trimmed))
      }
      return TypeSyntax(IdentifierTypeSyntax(name: named.name.trimmed
))
    }
    return base
  }
}
}

