    return statements.flatMap { codeBlockItem in
      if let guardStmt = codeBlockItem.item.as(GuardStmtSyntax.self) {
        return
        return guardStmt.lookupFromSequentialParent(
          identifier,
          at: lookUpPosition,
          with: config
